using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Reflection;
using System.Collections.Generic;
using System.Text.RegularExpressions;
using System.Web.Script.Serialization;
using NetScope;
class FinalIntegrationTests {
 static int passed,failed;static readonly List<string> log=new List<string>();
 static string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"final-integration-data-"+DateTime.UtcNow.ToString("yyyyMMddHHmmss"));
 static DateTime now=DateTime.UtcNow;
 static void Check(bool condition,string why){if(!condition)throw new Exception(why);}
 static void Test(string name,Action action){try{action();passed++;Record("PASS "+name);}catch(Exception ex){failed++;Record("FAIL "+name+" :: "+ex.GetBaseException().Message);}}
 static void Record(string line){log.Add(line);Console.WriteLine(line);}
 static string Dir(string name){string p=Path.Combine(root,name);Directory.CreateDirectory(p);return p;}
 static AppSettings Settings(){var s=Defaults.Create();s.AiAutoEnabled=false;s.AutoMonitor=false;return s;}
 static AppController New(string name){string p=Dir(name);new Store(p).SaveSettings(Settings());return new AppController(p);}
 static string Csv(string dir,string body){string file=Path.Combine(dir,Guid.NewGuid().ToString("N")+".csv");File.WriteAllText(file,body,new UTF8Encoding(true));return file;}
 static string Devices(string dir){return Csv(dir,"ip,mac,name,device_type,download_bps,upload_bps,observed_at\r\n192.168.50.2,AA:BB:CC:11:22:33,RouterReportedOne,tablet,1000,100,2026-10-29T12:00:00+08:00\r\n192.168.50.3,AA:BB:CC:44:55:66,RouterReportedTwo,phone,2000,200,2026-10-29T12:00:00+08:00\r\n");}
 static HistoryPoint Point(string id,string name,string url){var at=DateTime.UtcNow.AddMinutes(-1);return new HistoryPoint{At=at,DownloadBps=100,UploadBps=50,SampleCount=15,SpanSeconds=30,DownloadPeakBps=500,UploadPeakBps=250,NetworkProfileId="test-profile",TrafficAdapterId="test-adapter",Probes=new List<ProbeResult>{new ProbeResult{At=at,TargetId=id,Name=name,Url=url,PathId="test-profile",Group="AI",StatusCode=401,Reachable=true,HttpMs=100,DnsMs=10,TcpMs=20,Outcome="AuthRequired"}}};}
 static void Private(object obj,string field,object value){typeof(AppController).GetField(field,BindingFlags.NonPublic|BindingFlags.Instance).SetValue(obj,value);}
 static void MustThrow(Action action,string why){bool threw=false;try{action();}catch{threw=true;}Check(threw,why);}
 static int Main(string[] args){
 Test("manual device labels survive controller restart",()=>{string dir;using(var c=New("labels-persist")){dir=c.DataDirectory;c.ImportGatewayCsv(Devices(dir));c.SetDeviceLabel("aa-bb-cc-11-22-33","My workstation","Windows PC");Check(c.Devices.First(d=>d.Ip.EndsWith(".2")).Name=="My workstation","label not applied");}using(var c=new AppController(dir)){c.ImportGatewayCsv(Devices(dir));var d=c.Devices.First(x=>x.Ip.EndsWith(".2"));Check(d.Name=="My workstation"&&d.Hint=="Windows PC","label not restored");Check(d.NameSource.Contains("人工"),"manual label source missing");}});
 Test("clearing manual label restores router name and type persistently",()=>{string dir;using(var c=New("labels-clear")){dir=c.DataDirectory;c.ImportGatewayCsv(Devices(dir));c.SetDeviceLabel("AA:BB:CC:11:22:33","Custom","Windows");c.SetDeviceLabel("AA:BB:CC:11:22:33","","");var d=c.Devices.First(x=>x.Ip.EndsWith(".2"));Check(d.Name=="RouterReportedOne"&&d.Hint=="tablet","clear must restore original name and hint");}using(var c=new AppController(dir)){c.ImportGatewayCsv(Devices(dir));Check(c.Devices.First(x=>x.Ip.EndsWith(".2")).Name=="RouterReportedOne","clear did not persist");}});
 Test("different MACs may share one friendly name without merging",()=>{using(var c=New("labels-same-name")){c.ImportGatewayCsv(Devices(c.DataDirectory));c.SetDeviceLabel("AA:BB:CC:11:22:33","One laptop","Windows");c.SetDeviceLabel("AA:BB:CC:44:55:66","One laptop","Windows");Check(c.Devices.Count(d=>d.Name=="One laptop")==2,"same name should not collapse two adapters");c.SetDeviceLabel("AA:BB:CC:11:22:33","","");Check(c.Devices.First(d=>d.Ip.EndsWith(".3")).Name=="One laptop","clearing one MAC affected another");}});
 Test("invalid device MAC cannot be bound",()=>{using(var c=New("labels-invalid")){MustThrow(()=>c.SetDeviceLabel("00:00:00:00:00:00","bad",""),"zero MAC accepted");MustThrow(()=>c.SetDeviceLabel("FF:FF:FF:FF:FF:FF","bad",""),"broadcast MAC accepted");MustThrow(()=>c.SetDeviceLabel("not-a-mac","bad",""),"invalid MAC accepted");}});
 Test("URL credentials rejected without overwriting settings",()=>{using(var c=New("url-userinfo")){var s=c.Settings;string previous=s.Targets[0].Url;s.Targets[0].Url="https://username:password@example.com/api";MustThrow(()=>c.SaveSettings(s),"URL userinfo accepted");Check(c.Settings.Targets[0].Url==previous,"failed save altered live settings");Check(new Store(c.DataDirectory).LoadSettings().Targets[0].Url==previous,"failed save altered stored settings");}});
 Test("invalid CSV cannot replace existing device snapshot",()=>{using(var c=New("invalid-csv")){c.ImportGatewayCsv(Devices(c.DataDirectory));int count=c.Devices.Count;foreach(string body in new[]{"name,mac\r\nA,11:22:33:44:55:66\r\n","ip,name\r\nnot-an-ip,broken\r\n","ip,name\r\n192.168.1.2,\"unterminated\r\n"}){string f=Csv(c.DataDirectory,body);MustThrow(()=>c.ImportGatewayCsv(f),"invalid CSV accepted");Check(c.Devices.Count==count,"failed import replaced good snapshot");}}});
 Test("unknown CSV throughput remains unavailable rather than zero",()=>{using(var c=New("missing-throughput")){string f=Csv(c.DataDirectory,"ip,download_bps,upload_bps\r\n192.168.1.2,NaN,Infinity\r\n192.168.1.3,-3,\r\n");c.ImportGatewayCsv(f);Check(c.Devices.All(d=>d.DownloadBps==null&&d.UploadBps==null&&d.ObservedAt==null),"unknown values converted into measurements");}});
 Test("AI summary excludes local MACs IPs labels custom names and URLs",()=>{using(var c=New("privacy-final")){var s=c.Settings;s.Targets.Add(new ProbeTarget{Id="secret-id",Name="PROJECT_LABEL_SECRET",Group="OFFICE_GROUP_SECRET",Url="https://corporate-secret.example/private?token=SECRET_QUERY",Enabled=true});c.SaveSettings(s);var h=Point("secret-id","PROJECT_LABEL_SECRET",s.Targets.Last().Url);new Store(c.DataDirectory).Append("history",h);Private(c,"history",new List<HistoryPoint>{h});var local=new LocalSample{TrafficRateReady=false,TrafficAdapterName="ADAPTER_NAME_SECRET",Gateway="10.123.45.67",ProxySummary="http://proxy-secret.example:7890",Adapters=new List<AdapterInfo>{new AdapterInfo{Name="ADAPTER_NAME_SECRET",Mac="AA:BB:CC:11:22:33",Addresses="10.123.45.67",IsUp=true,Description="PRIVATE_DRIVER_SECRET"}}};Private(c,"local",local);Private(c,"frame",new MonitorFrame{At=now,Local=local,Probes=h.Probes});c.ImportGatewayCsv(Devices(c.DataDirectory));c.SetDeviceLabel("AA:BB:CC:11:22:33","MY_DEVICE_NAME_SECRET","MY_PRIVATE_TYPE_SECRET");string r=c.BuildReport(true);foreach(string secret in new[]{"PROJECT_LABEL_SECRET","OFFICE_GROUP_SECRET","corporate-secret.example","SECRET_QUERY","ADAPTER_NAME_SECRET","10.123.45.67","proxy-secret.example","AA:BB:CC:11:22:33","PRIVATE_DRIVER_SECRET","MY_DEVICE_NAME_SECRET","MY_PRIVATE_TYPE_SECRET"})Check(!r.Contains(secret),"private field leaked: "+secret);Check(r.Contains("100.0"),"useful latency removed");}});
 Test("Store restart restores history metrics and UTC timestamps",()=>{string dir=Dir("history-restore");var store=new Store(dir);var h=Point("public","Service","https://example.com/");store.SaveSettings(Settings());store.Append("history",h);using(var c=new AppController(dir)){var loaded=c.GetHistory(TimeSpan.FromHours(24));Check(loaded.Count==1,"history not restored");Check(Math.Abs((loaded[0].At-h.At).TotalMilliseconds)<2,"timestamp timezone shifted");Check(loaded[0].SampleCount==15&&loaded[0].DownloadPeakBps==500&&loaded[0].Probes[0].StatusCode==401,"metric values not restored");}});
 Test("Store ignores corrupted trailing history record",()=>{string dir=Dir("history-tail");var store=new Store(dir);store.SaveSettings(Settings());store.Append("history",Point("a","A","https://a.example"));string file=Directory.GetFiles(dir,"history-*.jsonl").Single();File.AppendAllText(file,"{\"At\":\"interrupted");using(var c=new AppController(dir)){Check(c.GetHistory(TimeSpan.FromHours(24)).Count==1,"corrupt tail prevented valid history recovery");}});
 Test("Store can append valid records after a crash-truncated tail",()=>{string dir=Dir("history-append-after-tail");var store=new Store(dir);store.SaveSettings(Settings());store.Append("history",Point("a","A","https://a.example"));string file=Directory.GetFiles(dir,"history-*.jsonl").Single();File.AppendAllText(file,"{\"At\":\"interrupted");store=new Store(dir);store.Append("history",Point("b","B","https://b.example"));Check(store.LoadHistory(30).Count==2,"first new record joined corrupt tail and was lost");});
 Test("quota parser preserves unknown fields as unknown",()=>{var parser=typeof(QuotaClient).GetMethod("ParseSnapshot",BindingFlags.NonPublic|BindingFlags.Static);var data=new JavaScriptSerializer().DeserializeObject("{\"rateLimits\":{\"primary\":{},\"credits\":null},\"rateLimitResetCredits\":null}") as Dictionary<string,object>;var q=(QuotaSnapshot)parser.Invoke(null,new object[]{data});Check(q.Windows.Count==0&&q.CreditBalance==null&&q.HasCredits==null&&q.ResetCreditsAvailable==null&&q.ResetCreditExpiresAt==null,"missing quota converted to zero/false");});
 Test("UI settings save maps every current setting property",()=>{string path=args.Length>0?args[0]:"";Check(File.Exists(path),"MainForm source required for static settings audit");string source=File.ReadAllText(path);var match=Regex.Match(source,@"var s=new AppSettings\{([^}]+)\}");Check(match.Success,"settings initializer not found");foreach(var property in typeof(AppSettings).GetProperties()){Check(Regex.IsMatch(match.Groups[1].Value,@"\b"+Regex.Escape(property.Name)+@"\s*="),"UI save would reset setting: "+property.Name);}Check(source.Contains("var s=controller.Settings;s.AiAutoEnabled=!s.AiAutoEnabled"),"quick AI toggle must preserve settings clone");});
 Test("anonymous report distinguishes traffic warmup from measured zero",()=>{using(var c=New("traffic-warmup")){var local=new LocalSample{TrafficRateReady=false,DownloadBps=0,UploadBps=0};Private(c,"local",local);Private(c,"frame",new MonitorFrame{At=now,Local=local});string report=c.BuildReport(true);Check(report.Contains("流量计数器预热中，尚无有效速率"),"warmup state not explained");Check(!report.Contains("当前选中接口下行 0 B/s"),"warmup represented as measured zero");local.TrafficRateReady=true;report=c.BuildReport(true);Check(report.Contains("当前选中接口下行 0 B/s"),"real measured zero not reported");}});
 Test("last sent AI input is restored from history without rebinding current evidence",()=>{string dir=Dir("ai-input-history");var store=new Store(dir);store.SaveSettings(Settings());store.Append("ai",new{at=now.AddMinutes(-10),summary="FIRST_SENT_SAMPLE_111",analysis="old response"});store.Append("ai",new{at=now.AddMinutes(-5),summary="ACTUAL_SENT_SAMPLE_222",analysis="latest response"});store.Append("history",Point("new-current","Fresh network evidence","https://fresh.example"));using(var c=new AppController(dir)){Check(c.LastAiInput=="ACTUAL_SENT_SAMPLE_222","historical input was not restored exactly");Check(c.LastAiInput!=c.BuildReport(true),"historical AI result rebound to live evidence");}});
 Test("explicit last sent AI input file takes precedence over older history",()=>{string dir=Dir("ai-input-file");var store=new Store(dir);store.SaveSettings(Settings());store.Append("ai",new{at=now.AddMinutes(-10),summary="OLDER_SENT_SAMPLE_333",analysis="old response"});File.WriteAllText(Path.Combine(dir,"last-ai-input.txt"),"LATEST_SENT_SAMPLE_444",new UTF8Encoding(false));using(var c=new AppController(dir)){Check(c.LastAiInput=="LATEST_SENT_SAMPLE_444","explicit latest sent evidence not restored");}});
 Record("RESULT "+passed+" passed, "+failed+" failed. No monitoring timer, model call, or external network request was started by this harness.");
 File.WriteAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"final-integration-results.txt"),log,new UTF8Encoding(true));return failed==0?0:1;
 }
}


